#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i = 0; i < 10; i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);

    for(int i = 0; i < m; i++){
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
    }

    // Fast adjacency check using sorted adjacency lists + binary search
    for(int u = 1; u <= n; u++){
        sort(adj[u].begin(), adj[u].end());
        sort(radj[u].begin(), radj[u].end());
    }

    auto has_edge = [&](int u, int v) -> bool {
        auto& a = adj[u];
        return binary_search(a.begin(), a.end(), v);
    };

    auto has_redge = [&](int u, int v) -> bool {
        // v -> u exists?
        auto& a = radj[u];
        return binary_search(a.begin(), a.end(), v);
    };

    auto now_f = chrono::steady_clock::now;
    auto start_time = now_f();
    auto elapsed_ms = [&](){return chrono::duration_cast<chrono::milliseconds>(now_f()-start_time).count();};

    // Check DAG - topological sort for longest path
    {
        vector<int> indeg(n+1, 0);
        for(int u = 1; u <= n; u++) for(int v : adj[u]) indeg[v]++;
        queue<int> q;
        for(int u = 1; u <= n; u++) if(indeg[u] == 0) q.push(u);
        vector<int> topo;
        topo.reserve(n);
        while(!q.empty()){
            int u = q.front(); q.pop(); topo.push_back(u);
            for(int v : adj[u]) if(--indeg[v] == 0) q.push(v);
        }
        if((int)topo.size() == n){
            vector<int> dp(n+1, 1), nxt(n+1, -1);
            for(int i = n-1; i >= 0; i--){
                int u = topo[i]; dp[u] = 1; nxt[u] = -1;
                for(int v : adj[u]){
                    if(dp[v] + 1 > dp[u]){
                        dp[u] = dp[v] + 1;
                        nxt[u] = v;
                    }
                }
            }
            int bs = topo[0];
            for(int u : topo) if(dp[u] > dp[bs]) bs = u;
            vector<int> path;
            for(int u = bs; u != -1; u = nxt[u]) path.push_back(u);
            cout << path.size() << "\n";
            for(int i = 0; i < (int)path.size(); i++){
                if(i) cout << ' ';
                cout << path[i];
            }
            cout << "\n";
            return 0;
        }
    }

    mt19937 rng(42);
    vector<int> best_path;

    // Greedy extension from back with Warnsdorff + randomness
    auto extend_back = [&](vector<int>& path, vector<int>& pos) -> bool {
        int c = path.back();
        int best = -1, best_score = INT_MAX;
        for(int v : adj[c]){
            if(pos[v] != -1) continue;
            int s = 0;
            for(int w : adj[v]) if(pos[w] == -1) s++;
            if(s < best_score || (s == best_score && (rng() & 1))){
                best_score = s;
                best = v;
            }
        }
        if(best == -1) return false;
        pos[best] = (int)path.size();
        path.push_back(best);
        return true;
    };

    // Greedy extension from front with Warnsdorff
    auto extend_front = [&](vector<int>& path, vector<int>& pos) -> bool {
        int c = path[0];
        int best = -1, best_score = INT_MAX;
        for(int v : radj[c]){
            if(pos[v] != -1) continue;
            int s = 0;
            for(int w : radj[v]) if(pos[w] == -1) s++;
            if(s < best_score || (s == best_score && (rng() & 1))){
                best_score = s;
                best = v;
            }
        }
        if(best == -1) return false;
        path.insert(path.begin(), best);
        for(int i = 0; i < (int)path.size(); i++) pos[path[i]] = i;
        return true;
    };

    // Full extend both directions
    auto full_extend = [&](vector<int>& path, vector<int>& pos){
        bool changed = true;
        while(changed){
            changed = false;
            while(extend_back(path, pos)) changed = true;
            while(extend_front(path, pos)) changed = true;
        }
    };

    // Vertex insertion: try to insert unvisited vertices into the path
    auto vertex_insert = [&](vector<int>& path, vector<int>& pos) -> bool {
        bool any = false;
        for(int v = 1; v <= n; v++){
            if(pos[v] != -1) continue;
            // Try prepend
            if(has_edge(v, path[0])){
                path.insert(path.begin(), v);
                for(int j = 0; j < (int)path.size(); j++) pos[path[j]] = j;
                any = true;
                continue;
            }
            // Try append
            if(has_edge(path.back(), v)){
                pos[v] = (int)path.size();
                path.push_back(v);
                any = true;
                continue;
            }
            // Try insert between consecutive
            for(int i = 0; i + 1 < (int)path.size(); i++){
                if(has_edge(path[i], v) && has_edge(v, path[i+1])){
                    path.insert(path.begin() + i + 1, v);
                    for(int j = i+1; j < (int)path.size(); j++) pos[path[j]] = j;
                    any = true;
                    break;
                }
            }
        }
        return any;
    };

    // Perturbation: remove random suffix and re-extend
    auto perturb_and_extend = [&](vector<int>& path, vector<int>& pos) -> bool {
        int orig_len = (int)path.size();
        if(orig_len <= 3) return false;

        // Strategy 1: Try back-edges from tail to interior, truncate and re-extend
        int tail = path.back();
        vector<int> back_targets;
        for(int v : adj[tail]){
            if(pos[v] != -1 && pos[v] < (int)path.size() - 2){
                back_targets.push_back(pos[v]);
            }
        }

        if(!back_targets.empty()){
            shuffle(back_targets.begin(), back_targets.end(), rng);
            int tries = min((int)back_targets.size(), 3);

            vector<int> save_path = path;
            vector<int> save_pos = pos;

            for(int t = 0; t < tries; t++){
                int j = back_targets[t];
                // Keep path[0..j], then tail, free vertices j+1..end-1
                // We need edge path[j] -> tail? No we have tail -> path[j].
                // So new path: path[0..j-1], then we need to get to tail somehow
                // Actually: we can do path[0..j], then since tail->path[j] exists,
                // if we reverse the segment j..end we'd need reverse edges.

                // Alternative: just truncate path to [0..j] freeing j+1..end
                // and re-extend from path[j]
                path = save_path;
                pos = save_pos;

                // Free vertices from j+1 onward
                for(int i = j+1; i < (int)path.size(); i++){
                    pos[path[i]] = -1;
                }
                path.resize(j+1);

                full_extend(path, pos);
                vertex_insert(path, pos);
                full_extend(path, pos);

                if((int)path.size() > orig_len){
                    return true;
                }
            }

            // Restore best
            if((int)path.size() < orig_len){
                path = save_path;
                pos = save_pos;
            }
        }

        // Strategy 2: Try back-edges from head to interior (using reverse edges)
        int head = path[0];
        vector<int> front_targets;
        for(int v : radj[head]){
            if(pos[v] != -1 && pos[v] > 1){
                front_targets.push_back(pos[v]);
            }
        }

        if(!front_targets.empty()){
            shuffle(front_targets.begin(), front_targets.end(), rng);
            int tries = min((int)front_targets.size(), 3);

            vector<int> save_path = path;
            vector<int> save_pos = pos;

            for(int t = 0; t < tries; t++){
                int j = front_targets[t];
                // Free vertices 0..j-1
                for(int i = 0; i < j; i++){
                    pos[path[i]] = -1;
                }
                path.erase(path.begin(), path.begin() + j);
                for(int i = 0; i < (int)path.size(); i++) pos[path[i]] = i;

                full_extend(path, pos);
                vertex_insert(path, pos);
                full_extend(path, pos);

                if((int)path.size() > orig_len){
                    return true;
                }
            }

            if((int)path.size() < orig_len){
                path = save_path;
                pos = save_pos;
            }
        }

        // Strategy 3: Random suffix/prefix removal
        {
            vector<int> save_path = path;
            vector<int> save_pos = pos;

            int remove_len = rng() % max(1, min((int)path.size() / 3, 30)) + 1;
            bool from_back = rng() & 1;

            if(from_back){
                for(int i = (int)path.size() - remove_len; i < (int)path.size(); i++)
                    pos[path[i]] = -1;
                path.resize((int)path.size() - remove_len);
            } else {
                for(int i = 0; i < remove_len; i++)
                    pos[path[i]] = -1;
                path.erase(path.begin(), path.begin() + remove_len);
                for(int i = 0; i < (int)path.size(); i++) pos[path[i]] = i;
            }

            full_extend(path, pos);
            vertex_insert(path, pos);
            full_extend(path, pos);

            if((int)path.size() >= orig_len){
                return (int)path.size() > orig_len;
            }

            path = save_path;
            pos = save_pos;
        }

        return false;
    };

    // Main restart loop
    int restart_count = 0;
    while(elapsed_ms() < 3700 && (int)best_path.size() < n){
        restart_count++;
        int sv = rng() % n + 1;

        vector<int> path;
        vector<int> pos(n+1, -1);
        path.push_back(sv);
        pos[sv] = 0;

        full_extend(path, pos);
        vertex_insert(path, pos);
        full_extend(path, pos);

        if((int)path.size() > (int)best_path.size()) best_path = path;

        // Improvement loop
        int no_improve = 0;
        while(no_improve < 100 && elapsed_ms() < 3700 && (int)path.size() < n){
            int before = (int)path.size();
            perturb_and_extend(path, pos);
            if((int)path.size() > before){
                no_improve = 0;
                if((int)path.size() > (int)best_path.size()) best_path = path;
            } else {
                no_improve++;
            }
        }

        if((int)path.size() > (int)best_path.size()) best_path = path;
    }

    // Final: try vertex insertion on best path
    {
        vector<int> pos(n+1, -1);
        for(int i = 0; i < (int)best_path.size(); i++) pos[best_path[i]] = i;
        vertex_insert(best_path, pos);
    }

    cout << best_path.size() << "\n";
    for(int i = 0; i < (int)best_path.size(); i++){
        if(i) cout << ' ';
        cout << best_path[i];
    }
    cout << "\n";
    return 0;
}
